def _parse(version):
    if not isinstance(version, str) or version == "":
        raise ValueError("version must be a non-empty string")
    core, sep, pre = version.partition("-")
    if core == "":
        raise ValueError("empty core")
    core_parts = core.split(".")
    numbers = []
    for part in core_parts:
        if part == "" or any(ch not in "0123456789" for ch in part):
            raise ValueError("core identifiers must be digits")
        numbers.append(int(part))
    if not sep:
        return numbers, []
    if pre == "":
        raise ValueError("empty pre-release")
    identifiers = pre.split(".")
    for ident in identifiers:
        if ident == "":
            raise ValueError("empty pre-release identifier")
        for ch in ident:
            if not (ch in "0123456789" or "a" <= ch <= "z" or "A" <= ch <= "Z" or ch == "-"):
                raise ValueError("bad pre-release character")
    return numbers, identifiers


def compare_versions(a, b):
    core_a, pre_a = _parse(a)
    core_b, pre_b = _parse(b)
    for i in range(max(len(core_a), len(core_b))):
        x = core_a[i] if i < len(core_a) else 0
        y = core_b[i] if i < len(core_b) else 0
        if x != y:
            return -1 if x < y else 1
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1
    for x, y in zip(pre_a, pre_b):
        if x == y:
            continue
        x_num = x.isdigit() and x.isascii()
        y_num = y.isdigit() and y.isascii()
        if x_num and y_num:
            if int(x) != int(y):
                return -1 if int(x) < int(y) else 1
            continue
        if x_num != y_num:
            return -1 if x_num else 1
        return -1 if x < y else 1
    if len(pre_a) == len(pre_b):
        return 0
    return -1 if len(pre_a) < len(pre_b) else 1

