def _int(text):
    if text == "" or any(ch not in "0123456789" for ch in text):
        raise ValueError("expected an integer")
    return int(text)


def expand_cron_field(field, lo, hi):
    if not isinstance(field, str):
        raise ValueError("field must be a string")
    items = field.split(",")
    values = set()
    for raw in items:
        item = raw.strip()
        if item == "":
            raise ValueError("empty item")
        step = 1
        if "/" in item:
            head, sep, step_text = item.partition("/")
            if "/" in step_text:
                raise ValueError("bad step")
            step = _int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1")
        else:
            head = item
        if head == "*":
            start, end = lo, hi
        elif "-" in head:
            left, sep, right = head.partition("-")
            start, end = _int(left), _int(right)
            if start > end:
                raise ValueError("reversed range")
        else:
            start = end = _int(head)
            if "/" in item:
                raise ValueError("a single value cannot take a step")
        for value in (start, end):
            if value < lo or value > hi:
                raise ValueError("value out of range")
        values.update(range(start, end + 1, step))
    return sorted(values)

